function chordTitleParts(c){const title=c.measureName||c.name,derived=c.measureName&&c.name!==c.measureName?c.name.replace(c.measureName,'').replace(/^[\s·–—-]+/,'').trim():'';return {title,subtitle:c.subtitle||derived};}
