function exercise(number,progression,copy,{primary=true,pattern='d.d.d.d.',repeat='REPEAT',bpm=96,groove='click',subdivision='eighth',meter=4,title='',keyOptions=[]}={}){const drumToggle='<button type="button" class="groove-toggle" aria-label="Turn drum backing on" aria-pressed="false"><strong>Drums</strong><span class="groove-switch" aria-hidden="true"></span></button>';return `<article class="change-card ${primary?'essential':'extra'}" data-exercise-number="${number}" data-exercise-title="${title}"${keyOptions.length?` data-key-options='${JSON.stringify(keyOptions)}'`:''} data-audio-progression='${JSON.stringify(progression)}' data-audio-pattern="${pattern}" data-audio-bpm="${bpm}" data-audio-groove="${groove}" data-audio-subdivision="${subdivision}" data-audio-meter="${meter}" data-drums-enabled="false"><div class="change-top"><div class="change-number">${number}</div><p class="change-label">${primary?'ESSENTIAL PRACTICE':'EXTRA PRACTICE'}</p><em>${repeat}</em></div><div class="exercise-toolbar"><button type="button" class="play-exercise" aria-label="Follow exercise ${number}" aria-pressed="false">${playIcon()}<span>Follow Along</span></button>${drumToggle}<div class="exercise-tempo" aria-label="Example tempo"><button type="button" class="tempo-step" data-tempo-step="-4" aria-label="Decrease tempo">−</button><label><input class="exercise-tempo-value" type="number" inputmode="numeric" min="40" max="200" step="1" value="${bpm}" aria-label="Custom tempo"><span>BPM</span></label><button type="button" class="tempo-step" data-tempo-step="4" aria-label="Increase tempo">+</button></div></div><div class="measure-row${progression.some(Array.isArray)?' has-split-measure':''}${progression.length>4?' long-progression':''}" style="--bar-count:${progression.length}">${progression.map((id,index)=>{const slotsPerMeasure=(subdivision==='sixteenth'?4:2)*meter,barIndex=index%Math.max(1,Math.ceil(pattern.length/slotsPerMeasure)),barPattern=pattern.slice(barIndex*slotsPerMeasure,barIndex*slotsPerMeasure+slotsPerMeasure);return Array.isArray(id)?beatMeasure(id,barPattern,subdivision):measure(id,barPattern,subdivision,meter);}).join('')}</div><p class="exercise-copy">${copy}</p></article>`;}
function applyExercisePattern(card,pattern,subdivision='eighth',meter=4){const slotsPerMeasure=(subdivision==='sixteenth'?4:2)*meter,bars=Math.max(1,Math.ceil(pattern.length/slotsPerMeasure));card.dataset.audioPattern=pattern;card.dataset.audioSubdivision=subdivision;card.dataset.audioMeter=String(meter);card.querySelectorAll('.music-measure').forEach((measure,index)=>{const barPattern=pattern.slice((index%bars)*slotsPerMeasure,(index%bars+1)*slotsPerMeasure);measure.querySelectorAll('.count-row,.stroke-row').forEach(row=>row.remove());measure.insertAdjacentHTML('beforeend',rhythmMarkup(barPattern,subdivision,meter));});}
function applyExerciseProgression(card,progression){const pattern=card.dataset.audioPattern||'d.d.d.d.',subdivision=card.dataset.audioSubdivision||'eighth',meter=Number(card.dataset.audioMeter||4),slotsPerMeasure=(subdivision==='sixteenth'?4:2)*meter,bars=Math.max(1,Math.ceil(pattern.length/slotsPerMeasure)),row=card.querySelector('.measure-row');card.dataset.audioProgression=JSON.stringify(progression);row.classList.toggle('has-split-measure',progression.some(Array.isArray));row.classList.toggle('long-progression',progression.length>4);row.style.setProperty('--bar-count',progression.length);row.innerHTML=progression.map((id,index)=>{const barPattern=pattern.slice((index%bars)*slotsPerMeasure,(index%bars+1)*slotsPerMeasure);return Array.isArray(id)?beatMeasure(id,barPattern,subdivision):measure(id,barPattern,subdivision,meter);}).join('');}
const objectiveOneVisuals=()=>`<section class="objective-one-visuals" aria-label="Objective 1 visual guides"><p>VISUAL GUIDES · TAP TO ENLARGE</p><div><button type="button" data-objective-image="./images/objective-one/fretboard-and-down-strum.png" data-objective-caption="The fretting area and the direction of a down-strum."><img src="./images/objective-one/fretboard-and-down-strum.png" alt="Instrument fretboard and down-strum direction guide"></button><button type="button" data-objective-image="./images/objective-one/strum-directions.png" data-objective-caption="Down-strums travel toward the floor; up-strums return toward the ceiling."><img src="./images/objective-one/strum-directions.png" alt="Down-strum and up-strum direction guide"></button></div></section>`;
