const objectiveOneReturn=()=>`<li class="objective-one-return"><strong>Need the foundation again?</strong> <button type="button" data-return-objective-one>Review Objective 1</button> for string names, fret numbers, finger numbers, open and muted strings, and basic strumming direction.</li>`;
