function objectiveWhy(course,objective){
 if(objective==='one')return course.endsWith('young')?'Learn a small chord family and play a complete song pattern.':'Learn one repeating chord family and start playing real songs.';
 if(objective==='two')return course.endsWith('young')?'Add the next useful shapes when a song needs them.':'Add another useful chord family and open the door to more songs.';
 if(objective==='four')return 'Learn the movable major and minor shapes rooted on the E and A strings.';
 return course.endsWith('young')?'Add another song-ready change while keeping a steady beat.':'Add frequent, playable shapes before moving into full barre chords.';
}
function objectiveNoteWhy(course,objective){
 if(course==='guitar'&&objective==='one')return 'Most songs are built on a small chord family that repeats while the melody sits on top. These four shapes teach the movement and steady beat needed to begin playing complete songs.';
 if(course==='guitar'&&objective==='two')return 'The key of G opens the first door, but one family cannot cover every song. C and Am begin the C-major family, while E creates another useful sound and a strong move into Am.';
 if(course==='guitar'&&objective==='three')return 'These chords are chosen for frequency, musical importance, and playability. F-Alternative also provides a manageable bridge from open chords into the barre-chord lesson.';
 if(course==='guitar'&&objective==='four')return 'A barre turns finger 1 into a movable nut. B, Bm, F♯, and F♯m show the major and minor versions of the two shape families without adding unnecessary higher-fret chords yet.';
 if(objective==='one')return 'A small chord family and a steady beat are enough to begin playing complete song patterns. Learn the shapes first, then keep the movement going.';
 if(objective==='two')return 'A second chord family opens more songs and gives the hand new, useful transitions to practice.';
 return 'These additional shapes connect the core chord families and prepare the hand for a wider range of songs.';
}
