 section.addEventListener('change',e=>{const choice=e.target.closest('.strumming-chord-select');if(choice){const card=choice.closest('[data-audio-progression]'),id=choice.value,index=Number(choice.dataset.measureIndex||0),wasPlaying=card.querySelector('.play-exercise.playing');if(!byId[id])return;const progression=JSON.parse(card.dataset.audioProgression);progression[index]=id;card.dataset.audioProgression=JSON.stringify(progression);const button=choice.closest('.measure-heading,.strumming-chord-row')?.querySelector('.preview-chord');if(button){button.dataset.previewChord=id;button.setAttribute('aria-label',`Show ${byId[id].name} chord`);button.textContent=byId[id].measureName||byId[id].name;}close(true);if(wasPlaying)restartExerciseAtCurrentMeasure(card);return;}const requestedStrum=e.target.closest('.requested-strum-select');if(requestedStrum){const card=requestedStrum.closest('.song-example')?.querySelector('[data-audio-progression]'),selected=practiceSongStrums.find(item=>item.pattern===requestedStrum.value)||practiceSongStrums[0];if(!card)return;const wasPlaying=card.querySelector('.play-exercise.playing');applyExercisePattern(card,selected.pattern,selected.subdivision,selected.meter);close(true);if(wasPlaying)restartExerciseAtCurrentMeasure(card);return;}const countIn=e.target.closest('.exercise-count-in-select');if(countIn){const card=countIn.closest('[data-audio-progression]'),wasPlaying=card.querySelector('.play-exercise.playing');card.dataset.countInBeats=countIn.value;if(wasPlaying)restartExerciseAtCurrentMeasure(card);return;}const input=e.target.closest('.exercise-tempo-value');if(input)setExerciseTempo(input.closest('[data-audio-progression]'),input.value);});section.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('.exercise-tempo-value')){e.preventDefault();e.target.blur();}if((e.key==='Enter'||e.key===' ')&&e.target.matches('.music-measure')){e.preventDefault();e.target.click();}});
 section.addEventListener('click',e=>{if(e.target.closest('.strumming-chord-select'))return;const visual=e.target.closest('[data-objective-image]');if(visual){imageDialogImage.src=visual.dataset.objectiveImage;imageDialogImage.alt=visual.querySelector('img')?.alt||'Objective 1 visual guide';imageDialogCaption.textContent=visual.dataset.objectiveCaption||'';imageDialog.showModal();return;}const returnToOne=e.target.closest('[data-return-objective-one]');if(returnToOne){showObjective('one');section.querySelector('.objective-heading-area')?.scrollIntoView({behavior:'smooth',block:'start'});return;}const play=e.target.closest('[data-play-chord]');if(play){if(requireSound())return;resetExamples();const chord=byId[play.dataset.playChord];play.classList.add('playing');chordPlayer.play(chord).catch(()=>{}).finally(()=>setTimeout(()=>play.classList.remove('playing'),420));return;}const drums=e.target.closest('.groove-toggle');if(drums){const card=drums.closest('[data-audio-progression]'),enabled=card.dataset.drumsEnabled!=='true';card.dataset.drumsEnabled=String(enabled);drums.setAttribute('aria-pressed',String(enabled));drums.setAttribute('aria-label',`Turn drum backing ${enabled?'off':'on'}`);if(card.querySelector('.play-exercise.playing'))chordPlayer.setExerciseGroove(enabled?'rock':'click');return;}const tempo=e.target.closest('[data-tempo-step]');if(tempo){const card=tempo.closest('[data-audio-progression]');setExerciseTempo(card,Number(card.dataset.audioBpm||84)+Number(tempo.dataset.tempoStep));return;}const demo=e.target.closest('.play-exercise');if(demo){if(demo.classList.contains('playing')){chordPlayer.stop();resetExamples();return;}if(requireSound())return;chordPlayer.stop();resetExamples();const card=demo.closest('[data-audio-progression]'),raw=JSON.parse(card.dataset.audioProgression),progression=raw.map(item=>Array.isArray(item)?item.map(id=>byId[id]).filter(Boolean):byId[item]).filter(Boolean),beatTimeline=JSON.parse(card.dataset.audioBeatProgression||'[]').map(id=>byId[id]).filter(Boolean),bpm=Number(card.dataset.audioBpm||84),groove=card.dataset.drumsEnabled==='true'?'rock':'click';demo.classList.add('playing');demo.setAttribute('aria-pressed','true');demo.querySelector('span').textContent='Stop';chordPlayer.playExercise(progression,card.dataset.audioPattern,bpm,cue=>showExerciseCue(card,cue),groove,Number(card.dataset.startMeasure||0),card.dataset.audioSubdivision||'eighth',card.dataset.beatTicks==='true',Number(card.dataset.audioMeter||4),Number(card.dataset.countInBeats||0),beatTimeline,card.closest('.custom-dynamic-progression')?customBackingMix(card):null).then(started=>{if(!started)resetExamples();}).catch(()=>resetExamples());return;}const course=e.target.closest('[data-course-tab]');if(course){chordPlayer.stop();resetExamples();return showCourse(course.dataset.courseTab);}const pathSwitch=e.target.closest('[data-path-switch]');if(pathSwitch){chordPlayer.stop();resetExamples();const family=currentCourse.startsWith('bar-')?'bar':'uke';return showCourse(`${family}-${pathSwitch.dataset.pathSwitch}`,currentObjective);}const tab=e.target.closest('[data-objective-tab]');if(tab){chordPlayer.stop();resetExamples();return showObjective(tab.dataset.objectiveTab);}const b=e.target.closest('[data-preview-chord]');if(b)return show(b.dataset.previewChord,true);const measure=e.target.closest('.music-measure');if(measure){const card=measure.closest('[data-audio-progression]');if(card){selectStartMeasure(card,Number(measure.dataset.measureIndex));const playButton=card.querySelector('.play-exercise');if(playButton.classList.contains('playing')){chordPlayer.stop();resetExamples();playButton.click();}}return;}if(e.target.closest('.preview-close')||e.target===backdrop)close(true);});
 const stopPlayback=()=>{chordPlayer.stop();resetExamples();};document.addEventListener('keydown',e=>{if(e.key==='Escape')close(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden){stopPlayback();if(isiOS){iosPrimed=false;soundCheck.classList.remove('ready');soundCheck.textContent='Enable iPhone Sound';}}});window.addEventListener('pagehide',stopPlayback);return{section,stopPlayback,syncSound};
